package recs

import (
	"sort"
	"strings"

	"golang.org/x/text/cases"
)

// The three score tiers (recommendation-sorting spec, score model): the
// constants pin the dominance order — any tag affinity ranks below a new
// episode, which ranks below a resume point — and the context bonuses
// stack additively.
const (
	// BonusInProgress is the resume-point tier: a positive, not-yet-complete
	// progress row on the entity. The top tier — nothing outranks a
	// partially-watched entity.
	BonusInProgress = 1000.0

	// BonusNewEpisode is the fresh-episode tier: a started series carrying a
	// discovered-in-window unwatched episode (D3).
	BonusNewEpisode = 500.0

	// TagCap is the affinity ceiling: the tag component never exceeds it, so
	// accumulated interest can never buy its way into a context tier.
	TagCap = 400.0
)

// EntityState is the read-time context of one browsable video entity: the
// context facts the api composes from batched store reads, plus the
// entity's tags — the convention genres array (D1), verbatim from the
// winning document (the series document for episodes and series, the item
// document for films/tv items).
type EntityState struct {
	// InProgress holds when a positive progress row exists on the entity
	// (the item itself, or any episode of a series) and the entity has NOT
	// completed — a watched-to-the-end entity never carries it.
	InProgress bool

	// NewEpisode holds for a started series that has at least one episode
	// item with no progress and no watched row, discovered within the
	// 30-day window (D3). The api resolves startedness and the window;
	// recs sees the fact alone.
	NewEpisode bool

	// Tags are the entity's genres as the winning document carries them —
	// unnormalized here; Score normalizes each key before the weight read.
	// Absent genres score honestly: an empty list contributes zero.
	Tags []string
}

// Weights is the learned interest per tag key, keyed exactly as
// NormalizeTag returns it — one entry per tag the janitor has applied a
// completion to (D5). Missing keys are the base: weight(t) = 1 +
// interest(t), interest 0, so every parsed tag carries an equal base
// score.
type Weights map[string]float64

// tagFold is the shared Unicode casefolder behind NormalizeTag. A Caser is
// safe for concurrent use.
var tagFold = cases.Fold()

// NormalizeTag is the ONE tag-key normalization (D1): trim surrounding
// whitespace, then Unicode casefold — "  Драма " and "дРАМА" are one tag.
// Every weight read (Score) and every weight write (the janitor apply)
// passes through it; keys stored raw could split one genre across two
// weights.
func NormalizeTag(tag string) string {
	return tagFold.String(strings.TrimSpace(tag))
}

// Score derives the entity's recommendation score — 1000·inProgress +
// 500·newEpisode + min(Σ weight(t), 400) — at read time. It is pure: no
// store, no clock, no hidden state; the cap applies to the tag component
// alone, so the context bonuses always stack past it.
func Score(e EntityState, w Weights) float64 {
	s := 0.0
	if e.InProgress {
		s += BonusInProgress
	}
	if e.NewEpisode {
		s += BonusNewEpisode
	}
	sum := 0.0
	for _, t := range e.Tags {
		sum += 1 + w[NormalizeTag(t)]
	}
	return s + min(sum, TagCap)
}

// Entry is one scored surface row: the identity the tie-break needs (the
// served display name, then id) beside its derived score and its watched
// state (D4) — the caller stamps Watched from the ledger before ordering;
// recs sees the fact alone, never the ledger.
type Entry struct {
	ID          string
	DisplayName string
	Score       float64

	// Watched sinks the entry below every unwatched one (D4): on collection
	// grids a completed element can no longer outrank an unstarted one
	// through tag affinity. False — the zero value — keeps the entry in the
	// unwatched partition, so surfaces that do not know watched state
	// (today's unwired callers) order exactly as before.
	Watched bool
}

// Order sorts entries in place into served order (D2, D4): every unwatched
// entry before every watched one, each partition score descending, ties by
// display name ascending, then by id — the alphabetical floor, the
// deterministic fallback every scored surface shares.
func Order(entries []Entry) {
	sort.Slice(entries, func(i, j int) bool {
		a, b := entries[i], entries[j]
		if a.Watched != b.Watched {
			return !a.Watched
		}
		if a.Score != b.Score {
			return a.Score > b.Score
		}
		if a.DisplayName != b.DisplayName {
			return a.DisplayName < b.DisplayName
		}
		return a.ID < b.ID
	})
}
